<?php
require_once 'auth.php';require_role(['super_admin','registrar']);require_once 'db.php';
$message='';$type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try {

 if(!verify_csrf()){$message='Invalid request.';$type='error';}else{$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$note=trim($_POST['note']??'');
  $s=mysqli_prepare($conn,'SELECT r.*,s.batch,s.section FROM results r JOIN students s ON s.student_id=r.student_id WHERE r.id=? LIMIT 1');mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($s));
  if(!$r){$message='Result not found.';$type='error';}elseif(semester_is_locked($conn,$r['year'],$r['semester'],$r['batch'],$r['section'])){$message='This semester is locked.';$type='error';}elseif($r['approval_status']!=='pending' || result_is_protected($r)){$message='Only pending results can be reviewed. Reopen an approved result first.';$type='error';}elseif(!in_array($action,['approve','reject'],true)){$message='Invalid action.';$type='error';}else{$new=$action==='approve'?'approved':'rejected';$by=$_SESSION['admin_username'];$pub=$new==='approved'?$r['publish_status']:'draft';$u=mysqli_prepare($conn,'UPDATE results SET approval_status=?,approval_note=?,approved_by=?,approved_at=NOW(),publish_status=? WHERE id=? AND approval_status=\'pending\'');mysqli_stmt_bind_param($u,'ssssi',$new,$note,$by,$pub,$id);mysqli_stmt_execute($u);revoke_student_verifications($conn,$r['student_id']);audit_log($conn,($action==='approve'?'RESULT_APPROVED':'RESULT_REJECTED'),'result',(string)$id,$r['student_id'].' '.$r['subject_code'].' '.$note);$message='Result '.($new==='approved'?'approved':'rejected').'.';}
 }

 } catch(mysqli_sql_exception $ex) { mysqli_rollback($conn); $message='This change could not be saved. The record may be locked, protected or changed by another user. Refresh and try again.'; $type='error'; }
}
$filter=$_GET['status']??'pending';if(!valid_approval_status($filter))$filter='pending';$st=mysqli_prepare($conn,'SELECT r.*,s.name FROM results r JOIN students s ON s.student_id=r.student_id WHERE r.approval_status=? ORDER BY r.id DESC LIMIT 200');mysqli_stmt_bind_param($st,'s',$filter);mysqli_stmt_execute($st);$rows=mysqli_stmt_get_result($st);
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result Approvals</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content"><section class="page-heading"><div><span class="page-kicker">Academic Control</span><h1>Result Approvals</h1><p>Review submitted results before they are eligible for publication.</p></div></section><?php if($message):?><div class="message <?=$type?>"><?=e($message)?></div><?php endif;?><div class="filter-chips"><?php foreach(['pending'=>'Pending','approved'=>'Approved','rejected'=>'Rejected'] as $k=>$v):?><a class="filter-chip" href="?status=<?=$k?>"><?=$v?></a><?php endforeach;?></div><section class="feature-card wide-card"><div class="table-wrapper"><table><thead><tr><th>Student</th><th>Term</th><th>Subject</th><th>Marks</th><th>Grade</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><strong><?=e($r['student_id'])?></strong><br><small><?=e($r['name'])?></small></td><td>Y<?=e($r['year'])?> S<?=e($r['semester'])?></td><td><?=e($r['subject_code'])?><br><small><?=e($r['subject'])?> · <?=e(result_attempt_label($r))?><?=((int)$r['includes_gpa']?'':' · Non-GPA')?></small></td><td><?=e($r['marks'])?></td><td><?=e($r['grade'])?></td><td><span class="status-pill <?=e($r['approval_status'])?>"><?=e(approval_status_label($r['approval_status']))?></span></td><td><?php if($r['approval_status']==='pending'):?><form method="post" class="inline-approval"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="note" placeholder="Optional note"><button class="btn-small" name="action" value="approve">Approve</button><button class="btn-small danger" name="action" value="reject">Reject</button></form><?php else:?><?=e($r['approval_note']?:'—')?><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></section></main><?php include 'footer.php';?></div></body></html>